%[text]{"align":"center"} ![](text:image:154b)
%[text]{"align":"center"} ![](text:image:7fae)
%[text]{"align":"center"} ![](text:image:940d)
%[text]{"align":"center"} ![](text:image:1375)
% Physical constant
rho = 1.2;
cp = 1000;
k = 0.02;
u = 5;
q1 = 1000000;
h = 10000;

% Simulation condition
T0 = 20;
Tinf = 20;

n = 200;
x = linspace(0,10,n)';
dx = x(2) - x(1);
dt = 0.01;
tfinal = 10;
nt = tfinal/dt;

% Initial condition
T = 0*x + T0;

figure %[output:787935fd]
pt = plot(x,T); %[output:787935fd]
ylim([0 250]) %[output:787935fd]
xregion(1,2) %[output:787935fd]

for it = 1:nt %[output:group:6ee29f18]

    % Assemble A and b
    A = zeros(n);
    b = zeros(n,1);
    for ii = 2:n-1
        % Transient
        A(ii,ii) = A(ii,ii) + rho*cp/dt;
        b(ii) = b(ii) + rho*cp*T(ii)/dt;

        % Advection
        A(ii,ii)   = A(ii,ii)   + rho*cp*u/dx;
        A(ii,ii-1) = A(ii,ii-1) - rho*cp*u/dx;

        % Diffusion
        A(ii,ii)   = A(ii,ii) + 2*k/dx^2;
        A(ii,ii-1) = A(ii,ii-1) - k/dx^2;
        A(ii,ii+1) = A(ii,ii+1) - k/dx^2;

        % Source Term
        if x(ii) >= 1 && x(ii) <= 2
            b(ii) = b(ii) + q1;
        elseif x(ii) > 2
            A(ii,ii) = A(ii,ii) + h;
            b(ii) = b(ii) + h*Tinf;
        end
    end

    % Add boundary condition
    
%[text] T\_1 = 20
    A(1,1) = 1;
    b(1) = 20;
    
%[text] dT/dx(n) = 0  --- \> (T(n) - T(n-1)) / dx = 0
    A(n,n) = 1;
    A(n,n-1) = -1;
    b(n) = 0;

    % Solve for a time step
    T = A\b;

    % Plot
    pt.YData = T; %[output:787935fd]
    drawnow
end %[output:group:6ee29f18]


